"""navera_lite/sim/sensors.py — the error models of the simulated sensors, and the statistics that check them:
first-order Gauss–Markov noise (the GPS receiver), its stationary σ and autocorrelation, and the Rayleigh law of a
2-D Gaussian error (the vision profiles). Part of NAVERA Lite, the course's teaching stack (mission 31).
Written for the course; it is not NAVERA code.

The Gauss–Markov recursion (lesson §4), one axis, step dt, correlation time tau_s, noise strength q (m/√s):
    x[k+1] = a·x[k] + q·√dt·w[k]        a = 1 − dt / tau_s,   w[k] independent N(0, 1)
"""
import math

import numpy as np

GPS_TAU_S = 20.0          # the simulated receiver's correlation time (s)
GPS_Q = 0.6               # its noise strength (m/√s)
GPS_DT_S = 0.2            # its period: 5 fixes per second


# TODO 4 ---------------------------------------------------------------------------------------
def gauss_markov(n, dt, tau_s, q, rng, x0=0.0):
    """n samples of first-order Gauss–Markov noise on one axis (lesson §4), starting from x0.

    n ≥ 1 samples; dt, tau_s in s (0 < dt < 2·tau_s, else ValueError); q in m/√s; rng: a numpy Generator
    (np.random.default_rng(seed)) from which ALL n standard normal numbers w are drawn at once, first thing
    (rng.standard_normal(n)), so a seed always gives the same noise. Returns a numpy array of n floats: sample k is
    the value after k + 1 steps (sample 0 = a·x0 + q·√dt·w[0]).
    Example: gauss_markov(3, 0.2, 20.0, 0.6, np.random.default_rng(0)) → array([0.0337, -0.0020, 0.1698])
             (rounded to 4 decimals)
    """
    if not 0.0 < dt < 2.0 * tau_s:
        raise ValueError(f"dt must be between 0 and 2·tau_s, got dt={dt}, tau_s={tau_s}")
    w = rng.standard_normal(int(n))
    a = 1.0 - dt / tau_s
    b = q * math.sqrt(dt)
    out = np.empty(int(n))
    x = float(x0)
    for k in range(int(n)):
        x = a * x + b * w[k]
        out[k] = x
    return out


# TODO 5 ---------------------------------------------------------------------------------------
def stationary_sigma(dt, tau_s, q):
    """The standard deviation the Gauss–Markov noise settles to after a long time (lesson §4): the σ for which
    Var(x[k+1]) = Var(x[k]). Same inputs as gauss_markov (0 < dt < 2·tau_s, else ValueError). Returns metres.
    Example: stationary_sigma(0.2, 20.0, 0.6) → 1.902   (1.90213…)
    """
    if not 0.0 < dt < 2.0 * tau_s:
        raise ValueError(f"dt must be between 0 and 2·tau_s, got dt={dt}, tau_s={tau_s}")
    a = 1.0 - dt / tau_s
    return q * math.sqrt(dt) / math.sqrt(1.0 - a * a)


# TODO 6 ---------------------------------------------------------------------------------------
def autocorrelation(x, lag):
    """The sample autocorrelation of a series at a lag (in samples): remove the mean m, then
    Σ (x[i] − m)(x[i + lag] − m) over i = 0 … len − 1 − lag, divided by Σ (x[i] − m)² over the whole series.
    lag = 0 gives 1.0. lag must be an int with 0 ≤ lag < len(x) (else ValueError).
    Example: autocorrelation([1.0, 2.0, 3.0, 4.0], 1) → 0.25
    """
    v = np.asarray(x, dtype=float)
    if isinstance(lag, bool) or int(lag) != lag or not 0 <= lag < len(v):
        raise ValueError(f"lag must be a whole number from 0 to len(x) − 1, got {lag!r}")
    lag = int(lag)
    d = v - v.mean()
    den = float(np.sum(d * d))
    if lag == 0:
        return 1.0
    return float(np.sum(d[:-lag] * d[lag:]) / den)


