def rayleigh_quantile(sigma, p):
    """The radius R that a share p of 2-D errors stay below, when the east and north errors are independent
    N(0, sigma²) (lesson §4): P(r ≤ R) = 1 − exp(−R² / (2σ²)). sigma ≥ 0 (metres), 0 ≤ p < 1 (else ValueError).
    Example: rayleigh_quantile(15.0, 0.5) → 17.66 (the median, 1.177 σ);  rayleigh_quantile(15.0, 0.95) → 36.72
    """
    if sigma < 0 or not 0.0 <= p < 1.0:
        raise ValueError(f"need sigma >= 0 and 0 <= p < 1, got sigma={sigma}, p={p}")
    return sigma * math.sqrt(-2.0 * math.log(1.0 - p))


# given — read it and use it, no need to change it
def sigma_for_median(median_m):
    """The per-axis σ of a 2-D Gaussian error whose MEDIAN horizontal error is median_m (the inverse of
    rayleigh_quantile(σ, 0.5)). Example: sigma_for_median(440.0) → 373.7 (the 'measured' day-vision profile)
    """
    # from mission 31 — finished: read it, use it, do not change it
    return float(median_m) / math.sqrt(2.0 * math.log(2.0))


# given — read it and use it, no need to change it
class GaussMarkov:
    """One axis of Gauss–Markov noise, stepped one sample at a time (the world's GPS receiver uses two).
    step(w) takes one standard normal number w and returns the new value (same recursion as gauss_markov).
    Example: g = GaussMarkov(0.2, 20.0, 0.6); g.step(1.0) → 0.268
    """

    def __init__(self, dt=GPS_DT_S, tau_s=GPS_TAU_S, q=GPS_Q, x0=0.0):
        self.a = 1.0 - dt / tau_s
        self.b = q * math.sqrt(dt)
        self.x = float(x0)

    def step(self, w):
        self.x = self.a * self.x + self.b * float(w)
        return self.x
